python3 - <<'EOF'
import json, subprocess, sys

def run(ops):
    p = subprocess.run([sys.executable, "access_auth.py"], input=json.dumps({"operations": ops}).encode(),
                       capture_output=True)
    return p.returncode, json.loads(p.stdout)

SALT = "00"*16
reg = {"operation":"register","user_id":"u","password":"password123","salt":SALT}
def sess(sid, now, lt): return {"operation":"authenticate_session","user_id":"u","password":"password123","session_id":sid,"now":now,"lifetime":lt}
def val(sid, now): return {"operation":"validate_session","session_id":sid,"now":now}
def term(sid, now): return {"operation":"terminate_session","session_id":sid,"now":now}
def adm(sid, now, port="p1", vlan=10): return {"operation":"check_admission","session_id":sid,"now":now,"port_id":port,"vlan_id":vlan}
def cfg(t): return {"operation":"set_session_idle_timeout","user_id":"u","idle_timeout":t}
def pol(rules): return {"operation":"set_admission_policy","user_id":"u","rules":rules}
def lim(n): return {"operation":"set_session_limit","user_id":"u","max_sessions":n}

# idle expiry + terminal stickiness over later hard expiry
rc, r = run([reg, cfg(50), sess("s1",0,1000), val("s1",60), val("s1",1001), term("s1",1002), val("s1",1003)])
for x in r["results"][2:]: print(x)
print("---")
# activity refresh extends idle window
rc, r = run([reg, cfg(50), sess("s1",0,1000), val("s1",40), val("s1",85), val("s1",95)])
for x in r["results"][2:]: print(x)
print("---")
# policy denial counts as activity
rc, r = run([reg, cfg(50), pol([{"port_id":"p1","vlan_id":10}]), sess("s1",0,1000),
             adm("s1",40,"p9",99),  # policy_denied at t=40 -> refresh
             adm("s1",85),          # accepted, refresh
             val("s1",95)])         # idle expired (85+50=145? no, 95<145 -> accepted!) 
for x in r["results"][3:]: print(x)
print("---")
# hard expiry does not refresh; hard check precedes idle
rc, r = run([reg, cfg(50), sess("s1",0,100), val("s1",100), val("s1",150)])
for x in r["results"][2:]: print(x)
print("---")
# terminate on idle-expired: denied, terminated_at null, stays idle terminal
rc, r = run([reg, cfg(50), sess("s1",0,1000), term("s1",60), val("s1",70), term("s1",80)])
for x in r["results"][2:]: print(x)
print("---")
# concurrency excludes idle-expired sessions
rc, r = run([reg, cfg(50), lim(1), sess("s1",0,1000), sess("s2",10,1000), sess("s3",60,1000)])
for x in r["results"][3:]: print(x)
print("---")
# new config only affects new sessions
rc, r = run([reg, sess("old",0,100), cfg(10), sess("new",0,100), val("old",50), val("new",50)])
for x in r["results"][3:]: print(x)
print("---")
# config 0 disables; overwrite semantics
rc, r = run([reg, cfg(10), cfg(0), sess("s1",0,100), val("s1",50)])
for x in r["results"]: print(x)
